contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint _val) public {
        c.SetMinSum(_val); if (__ESBMC_reverted()) return;
        uint minSumAfter = c.MinSum(); if (__ESBMC_reverted()) return;
        assert(minSumAfter == _val);
    }

    receive() external payable {}
}

